config..mcp.json:
{
  "mcpServers": {
    "awsknowledge": {
      "type": "http",
      "url": "https://knowledge-mcp.global.api.aws"
    },
    "aurora-dsql": {
      "command": "uvx",
      "args": [
        "awslabs.aurora-dsql-mcp-server@latest"
      ],
      "disabled": true,
      "env": {
        "FASTMCP_LOG_LEVEL": "ERROR"
      }
    },
    "cloudwatch": {
      "command": "uvx",
      "args": [
        "awslabs.cloudwatch-mcp-server@latest"
      ],
      "disabled": true,
      "env": {
        "FASTMCP_LOG_LEVEL": "ERROR",
        "AWS_REGION": "[your dsql cluster region, e.g. us-east-1 — must be a PromQL-enabled region]",
        "AWS_PROFILE": "[your aws profile name, e.g. default]"
      }
    }
  }
}

config.hooks/hooks.json:
{
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "mcp__aurora-dsql.*__transact",
        "hooks": [
          {
            "type": "prompt",
            "prompt": "A DSQL transact operation completed. Verify the result: if it was a DDL change, confirm the schema looks correct using get_schema. If it was a DML change, confirm the affected row count is expected. If it was an EXPLAIN operation, follow up on Query Plan Explainability within the DSQL skill"
          }
        ]
      }
    ]
  }
}
